def log2_backward_kernel(
    grad_ptr,
    x_ptr,
    out_ptr,
    n_elements,
    EVEN_N: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    """Fuse ATen's ``mul`` and ``div`` into one pass over contiguous inputs.

    ``EVEN_N`` drops the bounds mask when the caller knows the grid covers the
    tensor exactly, which is the common case for autograd's evenly shaped
    gradients.
    """
    pid = tl.program_id(axis=0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    if EVEN_N:
        grad = tl.load(grad_ptr + offsets)
        x = tl.load(x_ptr + offsets)
        denominator = (x.to(tl.float32) * LN2).to(x.dtype).to(tl.float32)
        # ATen's div is IEEE round-to-nearest while Triton's ``/`` is the
        # full-range approximation (up to one ulp off in float32), so ask for
        # the correctly rounded libdevice divide to stay bit-exact.
        grad_input = tl.math.div_rn(grad.to(tl.float32), denominator)
        tl.store(out_ptr + offsets, grad_input.to(out_ptr.dtype.element_ty))
    else:
        mask = offsets < n_elements
        grad = tl.load(grad_ptr + offsets, mask=mask, other=0.0)
        x = tl.load(x_ptr + offsets, mask=mask, other=1.0)
        denominator = (x.to(tl.float32) * LN2).to(x.dtype).to(tl.float32)
        grad_input = tl.math.div_rn(grad.to(tl.float32), denominator)
        tl.store(out_ptr + offsets, grad_input.to(out_ptr.dtype.element_ty), mask=mask)


@pointwise_dynamic(is_tensor=[True, True], promotion_methods=[(0, 1, "DEFAULT")])
@triton.jit
def log2_backward_strided(grad_output, x):
    """Strided/broadcast inputs reuse the generic pointwise codegen.

    Autograd hands back a contiguous gradient for a contiguous input, so this
    path is not the hot one; going through the shared machinery keeps every
    stride and broadcast layout correct without copying either operand.
    """
    denominator = (x.to(tl.float32) * LN2).to(x.dtype).to(tl.float32)
    return tl.math.div_rn(grad_output.to(tl.float32), denominator)


def log2_backward(grad_output, x):
    """ATen's ``log2`` input gradient: ``grad_output / (x * ln 2)``.

    One fused kernel replaces the two ATen kernels (``mul`` then ``div``) that
    the native formula launches when both operands are contiguous, which is what
    the autograd engine produces.  Strided or broadcast operands fall back to
    the shared pointwise implementation.
    """
