    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return log2_func(x)

    @staticmethod
    def backward(ctx, grad_output):
        (x,) = ctx.saved_tensors
        if not ctx.needs_input_grad[0]:
            return None
        return log2_backward(grad_output, x)


